import random, itertools
_R = "i ii iii iv".split()
_L = "abcd"
def _place(correct, wrongs, pos):
    opts = list(wrongs); opts.insert(pos, correct); return opts
def build():
    out = []; k = 0
    for q, opts, exp in D:
        pos = (k*3 + 1) % 4; k += 1
        out.append(dict(q=q, options=_place(opts[0], opts[1:], pos), answer=pos, exp=exp))
    rnd = random.Random(33)
    for head, pairs, exp in M:
        pos = k % 4; k += 1
        II = [b for _, b in pairs]; rnd.shuffle(II)
        corr = [II.index(b) for _, b in pairs]
        fmt = lambda p: ", ".join(f"{_L[i]}-{_R[j]}" for i, j in enumerate(p))
        perms = [p for p in itertools.permutations(range(4)) if list(p) != corr]
        wr = rnd.sample(perms, 3)
        q = head + " List I: " + "; ".join(f"({_L[i]}) {a}" for i, (a, _) in enumerate(pairs)) + " || List II: " + "; ".join(f"({_R[j]}) {b}" for j, b in enumerate(II))
        out.append(dict(q=q, options=_place(fmt(corr), [fmt(w) for w in wr], pos), answer=pos, exp=exp))
    for a, r, ans, exp in AR:
        out.append(dict(q=f"Assertion (A): {a} Reason (R): {r}", options=AR_OPTS, answer=ans, exp=exp))
    for head, items, exp in C:
        pos = (k + 2) % 4; k += 1
        lab = list(items); rnd.shuffle(lab)
        corr = [lab.index(it) for it in items]
        fmt = lambda p: ", ".join(f"({_L[i]})" for i in p)
        perms = [p for p in itertools.permutations(range(4)) if list(p) != corr]
        wr = rnd.sample(perms, 3)
        q = head + " " + " ".join(f"({_L[i]}) {t}" for i, (t, _) in enumerate(lab))
        out.append(dict(q=q, options=_place(fmt(corr), [fmt(w) for w in wr], pos), answer=pos, exp=exp))
    for i, (q, opts, exp) in enumerate(S):
        pos = (i * 3 + 2) % 4
        out.append(dict(q=q, options=_place(opts[0], opts[1:], pos), answer=pos, exp=exp))
    return out
mcqs = build()
